package EmployeeManagementSystem.controller;
import EmployeeManagementSystem.service.RequestScopeService;
import EmployeeManagementSystem.entity.*; import EmployeeManagementSystem.security.jwt.JwtUtil; import EmployeeManagementSystem.repository.EmployeeRepository; import EmployeeManagementSystem.service.LoanAdvanceService; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/loans") public class LoanAdvanceController{
 private final RequestScopeService scope;private final LoanAdvanceService s;private final JwtUtil jwt;private final EmployeeRepository er;public LoanAdvanceController(LoanAdvanceService s,JwtUtil j,EmployeeRepository e,RequestScopeService requestScope){this.scope=requestScope;this.s=s;jwt=j;er=e;}private String t(String a){if(a==null||!a.startsWith("Bearer "))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Authentication required.");return a.substring(7);}private String u(String a){return jwt.extractUsername(t(a));}private String r(String a){String x=jwt.extractRole(t(a));return x==null?"":x.replace("ROLE_","").toUpperCase();}private boolean mg(String x){return Set.of("ADMIN","HR","MANAGER").contains(x);}private RuntimeException bad(Exception e){return new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}
@GetMapping("/my") public List<LoanAdvance> my(@RequestHeader("Authorization")String a){return s.list(u(a),false);}
@GetMapping public List<LoanAdvance> list(@RequestHeader("Authorization")String a){return mg(r(a))?scope.visibleTo(r(a),u(a),s.list(u(a),true)):s.list(u(a),false);}
@PostMapping public LoanAdvance create(@RequestHeader("Authorization")String a,@RequestBody LoanAdvance x){String user=u(a);String name=er.findByRegisterEmployee_UserId(user).map(z->z.getFullName()).orElse(user);try{return s.create(x,user,name);}catch(Exception e){throw bad(e);}}
@PutMapping("/{id}") public LoanAdvance update(@RequestHeader("Authorization")String a,@PathVariable Long id,@RequestBody LoanAdvance x){try{return s.update(id,x,u(a));}catch(Exception e){throw bad(e);}}
@DeleteMapping("/{id}") public Map<String,Object> del(@RequestHeader("Authorization")String a,@PathVariable Long id){try{s.delete(id,u(a));return Map.of("success",true);}catch(Exception e){throw bad(e);}}
@PatchMapping("/{id}/review") public LoanAdvance review(@RequestHeader("Authorization")String a,@PathVariable Long id,@RequestBody Map<String,Object>b){scope.assertCanReviewById(r(a),u(a),s.list(u(a),true),id);if(!mg(r(a)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Management access required.");try{return s.review(id,String.valueOf(b.get("status")),String.valueOf(b.getOrDefault("comment","")),u(a));}catch(Exception e){throw bad(e);}}
@GetMapping("/{id}/schedule") public List<LoanRepayment> schedule(@RequestHeader("Authorization")String a,@PathVariable Long id){scope.assertCanAccessById(r(a),u(a),s.list(u(a),true),id);try{return s.schedule(id);}catch(Exception e){throw bad(e);}}
@PatchMapping("/{id}/repayments/{rid}/paid") public LoanRepayment paid(@RequestHeader("Authorization")String a,@PathVariable Long id,@PathVariable Long rid){scope.assertCanReviewById(r(a),u(a),s.list(u(a),true),id);if(!mg(r(a)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Management access required.");try{return s.markPaid(id,rid);}catch(Exception e){throw bad(e);}}
}
